import com.mirth.connect.connectors.http.HttpReceiverProperties;
import com.mirth.connect.connectors.vm.VmDispatcherProperties;
import com.mirth.connect.donkey.model.channel.SourceConnectorProperties;
import com.mirth.connect.model.Channel;
import com.mirth.connect.model.ChannelMetadata;
import com.mirth.connect.model.ChannelPruningSettings;
import com.mirth.connect.model.Connector;
import com.mirth.connect.model.Filter;
import com.mirth.connect.model.Transformer;
import com.mirth.connect.model.converters.ObjectXMLSerializer;
import com.mirth.connect.plugins.datatypes.fhir.FhirDataTypeProperties;
import com.mirth.connect.plugins.datatypes.fhir.FhirSerializationProperties;

/**
 * Writes the channel for the smoke test (.github/scripts/smoke-test.sh) as OIE channel XML, made
 * with the engine's own model classes and serializer, so it matches the engine version under test.
 *
 * An HTTP Listener on the given port with data type FHIR: Resource Types "Patient", inbound
 * validation, auto-generated OperationOutcome responses with ${fhirHttpStatus}, and FHIR XML out,
 * so the conversion in the isolated HAPI class loader runs too.
 *
 * Usage (single-file source launch): java -cp <engine and plugin jars> SmokeChannel.java <engine version> <port> <output file>
 */
public class SmokeChannel {

    public static final String CHANNEL_ID = "5e0b7e5f-f41c-4d1e-9a6c-000000000001";

    public static void main(String[] args) throws Exception {
        String version = args[0];
        String port = args[1];

        Channel channel = new Channel();
        channel.setId(CHANNEL_ID);
        channel.setName("FHIR smoke test");
        channel.setDescription("Generated by .github/smoke/SmokeChannel.java");
        channel.setRevision(1);
        channel.setNextMetaDataId(2);
        channel.setPreprocessingScript("return message;");
        channel.setPostprocessingScript("return;");
        channel.setDeployScript("return;");
        channel.setUndeployScript("return;");

        HttpReceiverProperties http = new HttpReceiverProperties();
        http.getListenerConnectorProperties().setPort(port);
        http.getSourceConnectorProperties().setResponseVariable(SourceConnectorProperties.RESPONSE_SOURCE_TRANSFORMED);
        http.setContextPath("/");
        http.setXmlBody(false);
        http.setResponseContentType("${fhirContentType}");
        http.setResponseStatusCode("${fhirHttpStatus}");

        FhirDataTypeProperties inbound = new FhirDataTypeProperties();
        FhirSerializationProperties in = (FhirSerializationProperties) inbound.getSerializerProperties().getSerializationProperties();
        in.setResourceTypes("Patient");
        FhirDataTypeProperties outbound = new FhirDataTypeProperties();
        FhirSerializationProperties out = (FhirSerializationProperties) outbound.getSerializerProperties().getSerializationProperties();
        out.setOutputFormat(FhirSerializationProperties.OutputFormat.XML);

        Connector source = new Connector("sourceConnector");
        source.setMetaDataId(0);
        source.setMode(Connector.Mode.SOURCE);
        source.setTransportName("HTTP Listener");
        source.setProperties(http);
        source.setEnabled(true);
        source.setFilter(new Filter());
        source.setTransformer(transformer(inbound, outbound));
        channel.setSourceConnector(source);

        Connector destination = new Connector("Destination 1");
        destination.setMetaDataId(1);
        destination.setMode(Connector.Mode.DESTINATION);
        destination.setTransportName("Channel Writer");
        destination.setProperties(new VmDispatcherProperties());
        destination.setEnabled(true);
        destination.setWaitForPrevious(true);
        destination.setFilter(new Filter());
        destination.setTransformer(transformer(noValidation(), noValidation()));
        destination.setResponseTransformer(transformer(noValidation(), noValidation()));
        channel.addDestination(destination);

        ChannelMetadata metadata = channel.getExportData().getMetadata();
        metadata.setEnabled(true);
        metadata.setPruningSettings(new ChannelPruningSettings());

        ObjectXMLSerializer serializer = ObjectXMLSerializer.getInstance();
        serializer.init(version);
        java.nio.file.Files.write(java.nio.file.Paths.get(args[2]), serializer.serialize(channel).getBytes(java.nio.charset.StandardCharsets.UTF_8));
    }

    private static Transformer transformer(FhirDataTypeProperties inbound, FhirDataTypeProperties outbound) {
        Transformer t = new Transformer();
        t.setInboundDataType("FHIR");
        t.setOutboundDataType("FHIR");
        t.setInboundProperties(inbound);
        t.setOutboundProperties(outbound);
        return t;
    }

    /** The destination does not validate again (see the README). */
    private static FhirDataTypeProperties noValidation() {
        FhirDataTypeProperties p = new FhirDataTypeProperties();
        ((FhirSerializationProperties) p.getSerializerProperties().getSerializationProperties()).setValidateInbound(false);
        return p;
    }
}
